style.css:
@-moz-document domain("chatgpt.com") {
/* Main background - deep dark purple */
body {
  background: #110022 !important;
  background-image:
    linear-gradient(0deg, transparent 24%, rgba(255,0,204,0.05) 25%, rgba(255,0,204,0.05) 26%, transparent 27%, transparent 74%, rgba(255,0,204,0.05) 75%, rgba(255,0,204,0.05) 76%, transparent 77%, transparent),
    linear-gradient(90deg, transparent 24%, rgba(0,255,255,0.05) 25%, rgba(0,255,255,0.05) 26%, transparent 27%, transparent 74%, rgba(0,255,255,0.05) 75%, rgba(0,255,255,0.05) 76%, transparent 77%, transparent) !important;
  background-size: 50px 50px !important;
  color: #00FFFF !important;
}

/* Headers and navigation */
header, nav, [role="navigation"] {
  background: linear-gradient(135deg, #1a0033 0%, #110022 100%) !important;
  border-bottom: 2px solid #FF00CC !important;
  box-shadow: 0 0 20px rgba(255,0,204,0.5) !important;
}

/* All text containers */
div, p, span, article {
  color: #00FFFF !important;
}

/* Buttons */
button {
  background: linear-gradient(135deg, #7500FF 0%, #FF00CC 100%) !important;
  color: #FFFFFF !important;
  border: 2px solid #00FFFF !important;
  box-shadow: 0 0 15px rgba(255,0,204,0.6), inset 0 0 10px rgba(0,255,255,0.3) !important;
  text-shadow: 0 0 5px #FF00CC !important;
  transition: all 0.3s ease !important;
}
button:hover {
  box-shadow: 0 0 25px rgba(0,255,255,0.8), inset 0 0 15px rgba(255,0,204,0.5) !important;
  transform: scale(1.05) !important;
}

/* Input fields and textareas */
input, textarea {
  background: #1a0033 !important;
  color: #00FFFF !important;
  border: 2px solid #7500FF !important;
  box-shadow: 0 0 10px rgba(117,0,255,0.5), inset 0 0 5px rgba(255,0,204,0.2) !important;
}
input:focus, textarea:focus {
  border-color: #FF00CC !important;
  box-shadow: 0 0 20px rgba(255,0,204,0.8) !important;
}

/* Chat messages */
[class*="message"], [class*="Message"] {
  background: rgba(26,0,51,0.8) !important;
  border-left: 3px solid #FF00CC !important;
  box-shadow: 0 0 10px rgba(0,255,255,0.3) !important;
}

/* Sidebar */
aside, [role="complementary"] {
  background: linear-gradient(180deg, #1a0033 0%, #110022 100%) !important;
  border-right: 2px solid #7500FF !important;
  box-shadow: 0 0 15px rgba(117,0,255,0.4) !important;
}

/* Links */
a {
  color: #FF00CC !important;
  text-shadow: 0 0 3px #FF00CC !important;
  transition: all 0.2s ease !important;
}
a:hover {
  color: #00FFFF !important;
  text-shadow: 0 0 8px #00FFFF !important;
}

/* Code blocks */
code, pre {
  background: #0d001a !important;
  border: 1px solid #7500FF !important;
  color: #FF00CC !important;
  box-shadow: 0 0 10px rgba(117,0,255,0.3) !important;
}

/* Scrollbars */
::-webkit-scrollbar {
  width: 12px !important;
  background: #110022 !important;
}
::-webkit-scrollbar-thumb {
  background: linear-gradient(180deg, #FF00CC 0%, #7500FF 100%) !important;
  border: 1px solid #00FFFF !important;
  box-shadow: 0 0 5px rgba(0,255,255,0.5) !important;
}
::-webkit-scrollbar-thumb:hover {
  box-shadow: 0 0 10px rgba(255,0,204,0.8) !important;
}
}
